import React, { useEffect, useState } from 'react';
import { Box, Typography, Paper, Button } from '@mui/material';
import { Margin, Store } from '@mui/icons-material';
import callApi from '../../Services/callApi';
import Swal from 'sweetalert2';
import { IInventoryTransactionIn, IInventoryTransactionOut, useInventoryTransaction } from '../../Context/InventoryTransactionContext';
// import image from 

const FlashList = ({ items }: any) => {
const {itemList,onLoadItemList} = useInventoryTransaction();
    const handleReceive = async (data: any) => {
        console.log(data)
        Swal.fire({
            title: "รับสินค้า",
            input: "number",
            inputAttributes: {
                autocapitalize: "off"
            },
            showCancelButton: true,
            confirmButtonText: "ยืนยัน",

        }).then((result) => {
            if (result.isConfirmed) {
                var newInventoryTransactionIn = {
                    source_type: 'GR',
                    source_id: 0,
                    item_id: data.id,
                    quantity: parseInt(result.value),
                    unit: data.unit
                }
                onCreateInventoryTransactionIn(newInventoryTransactionIn);
                
            }
        });


    }
    const onCreateInventoryTransactionIn = async(data:any)=>{
        // console.log(data);
        const result = await callApi.post('/inventory_transaction?type=in',[data]);
        if(result?.data?.status=='success'){
            Swal.fire('บันทึกสำเร็จ','','success')
            onLoadItemList();
        }else{
            Swal.fire('Create Inventory Transaction In Faild.','','error');
        }
    }
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            {items.map((item: any) => (
                <Paper key={item.id} sx={{ padding: 2, borderRadius: '16px', backgroundColor: 'white', boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)', display: 'flex', alignItems: 'center' }}>
                    <img src={'./image.png'} alt={item.name} style={{ width: '50px', height: '50px', marginRight: '16px', borderRadius: '8px' }} />
                    <Box sx={{ textAlign: 'left', color: 'gray', width: '100%' }}>
                        <Typography variant="h6" sx={{ fontWeight: 'bold' }}>{item.name}</Typography>
                        <Typography variant="body2">Quantity: {item.quantity} {item.unit}</Typography>
                        <Typography variant="body2">Price: {item.price} </Typography>
                        <Typography variant="body2">Description: {item.description}</Typography>
                        <Typography variant="body2">Category: {item.category}</Typography>
                        <Button sx={{ marginTop: 1 }} fullWidth color='primary' variant='outlined' onClick={() => handleReceive(item)}>รับสินค้า</Button>
                    </Box>
                </Paper>
            ))}
        </Box>
    );
};



const SupplyHome = () => {
    const {itemList,onLoadItemList} = useInventoryTransaction();
    useEffect(() => {
        onLoadItemList();
    }, [])

    return (
        <Box sx={{ display: 'flex', justifyContent: 'center', mt: 5 }}>
            <Box sx={{ width: '100%', padding: 2, margin: 3 }}>
                <Box sx={{ mb: 3 }}>
                    <Typography variant="h5" fontWeight="bold" gutterBottom>
                        <Store /> Stock
                    </Typography>
                    <Typography variant="body1" color="text.secondary">
                        Medicine & Medical Supply Management Stock
                    </Typography>
                </Box>
                <Box>
                    <FlashList items={itemList} />
                </Box>
            </Box>
        </Box>
    );
};

export default SupplyHome;
